/-- Order, strict badness, lower cutoff, upper product, in that order. -/
def actualPairMargins (b lower : ℝ) (v : Fin 2 → ℝ) : Fin 4 → ℝ :=
  ![v 1 - v 0, v 0 - b * v 1, v 0 + v 1 - lower, 1 - v 0 - v 1]

/-- Actual normalized prime logarithms, with the original labelled slots. -/
def logPoint (N : ℕ) (t : Fin 2 → Fin (N + 1)) : Fin 2 → ℝ :=
  fun i => Real.log ((t i).val : ℝ) / Real.log (N : ℝ)

/-- Read the two labelled coordinates as an ordered natural pair. -/
def tuplePair {N : ℕ} (t : Fin 2 → Fin (N + 1)) : ℕ × ℕ :=
  ((t 0).val, (t 1).val)

/-- Literal normalized distance on the outside of the strict badness wall. -/
def normalizedWall (b : ℝ) (N r q : ℕ) : ℝ :=
  (Real.log (r : ℝ) - b * Real.log (q : ℝ)) / Real.log (N : ℝ)
